7	
8	/// A domain-validation error (invalid value object input).
9	#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
10	pub enum DomainError {
11	    #[error("invalid email: {0}")]
12	    InvalidEmail(String),
13	    #[error("invalid slug: {0}")]
14	    InvalidSlug(String),
15	    #[error("invalid name: {0}")]
16	    InvalidName(String),
17	    #[error("invalid tenancy prn: {0}")]
18	    InvalidNodePrn(String),
19	}
20	
21	/// A validated email address. M0 rule: non-empty, exactly one `@`, non-empty local
22	/// and domain parts. Deliberately minimal — full RFC 5322 is out of scope.
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	pub struct Email(String);
25	
26	impl Email {
27	    pub fn parse(raw: &str) -> Result<Self, DomainError> {
28	        let s = raw.trim();
29	        let bad = |r: &str| DomainError::InvalidEmail(r.to_string());
30	        if s.is_empty() {
31	            return Err(bad(raw));
32	        }
33	        let (local, domain) = s.split_once('@').ok_or_else(|| bad(raw))?;
34	        if local.is_empty() || domain.is_empty() || domain.contains('@') {
35	            return Err(bad(raw));
36	        }
37	        Ok(Email(s.to_string()))
38	    }
39	
40	    #[must_use]
41	    pub fn as_str(&self) -> &str {
42	        &self.0
43	    }
44	}
45	
46	/// A principal's stable identity: its PRN (`prn:pgs:iam:::principal/<uuidv7>`). The UUID
47	/// (the PK/FK) is derived from the PRN's resource-id — stored once, never duplicated.
48	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
49	pub struct PrincipalId(Prn);
50	
51	impl PrincipalId {
52	    #[must_use]
53	    pub fn from_prn(prn: Prn) -> Self {
54	        PrincipalId(prn)
55	    }
56	
57	    #[must_use]
58	    pub fn uuid(&self) -> Uuid {
59	        self.0.resource_id()
60	    }
61	
62	    #[must_use]
63	    pub fn prn(&self) -> &Prn {
64	        &self.0
65	    }
66	
67	    #[must_use]
68	    pub fn canonical(&self) -> String {
69	        self.0.canonical()
70	    }
71	}
72	
73	#[cfg(test)]
74	mod tests {
75	    use super::*;
76	
77	    #[test]
78	    fn email_accepts_a_simple_address() {
79	        assert_eq!(Email::parse("  a@b.com ").unwrap().as_str(), "a@b.com");
80	    }
81	
82	    #[test]
83	    fn email_rejects_empty_missing_at_and_empty_parts() {
84	        for bad in ["", "  ", "nope", "@b.com", "a@", "a@@b", "a b"] {
85	            assert!(Email::parse(bad).is_err(), "expected {bad:?} to be rejected");
