102	/// Serve the HTTP surface on `addr` until `shutdown` resolves.
103	pub async fn serve_http(addr: SocketAddr, state: AppState, request_timeout: Duration, shutdown: impl std::future::Future<Output = ()> + Send + 'static) -> std::io::Result<()> {
104	    // `TimeoutLayer::new` is deprecated since tower-http 0.6.7 in favor of
105	    // `with_status_code`; `REQUEST_TIMEOUT` (408) reproduces `new`'s prior default.
