31	/// Starts an ephemeral Postgres container, connects, and runs migrations.
32	///
33	/// Returns `None` when Docker is unavailable and `CI` is unset (local skip path). Panics
34	/// when `CI` is set and Docker is unreachable — Docker must be present in CI.
35	pub async fn start_migrated_postgres() -> Option<(ContainerAsync<Postgres>, DatabaseConnection)> {
36	    let node = match Postgres::default().with_tag("16-alpine").start().await {
37	        Ok(n) => n,
38	        Err(e) => {
39	            if std::env::var_os("CI").is_some() {
40	                panic!("Docker is required for the round-trip test in CI: {e}");
41	            }
42	            eprintln!("skipping round-trip: Docker unavailable ({e})");
43	            return None;
44	        }
45	    };
46	
47	    let port = node.get_host_port_ipv4(5432).await.unwrap();
48	    let url = format!("REDACTED");
49	    let db = Database::connect(&url).await.unwrap();
50	    Migrator::up(&db, None).await.unwrap();
51	
52	    Some((node, db))
53	}
