55	/// Builds the real `router(AppState::new(db))` for `tower::ServiceExt::oneshot` HTTP tests.
56	#[allow(dead_code)]
57	pub fn app(db: DatabaseConnection) -> Router {
58	    router(AppState::new(db))
59	}
60	
61	/// Drives one request through the router and returns `(status, json body)`. `Value::Null`
62	/// stands in for an empty body (e.g. the archive/restore/health endpoints and `DELETE` 204
63	/// responses under test don't all have one).
64	#[allow(dead_code)]
65	pub async fn send(app: &Router, method: &str, uri: &str, body: Option<Value>) -> (StatusCode, Value) {
66	    let mut builder = Request::builder().method(method).uri(uri);
67	    let body = match body {
68	        Some(b) => {
69	            builder = builder.header("content-type", "application/json");
70	            Body::from(serde_json::to_vec(&b).unwrap())
71	        }
72	        None => Body::empty(),
73	    };
74	    let request = builder.body(body).unwrap();
75	    let response = app.clone().oneshot(request).await.unwrap();
76	    let status = response.status();
77	    let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
78	    let value = if bytes.is_empty() { Value::Null } else { serde_json::from_slice(&bytes).unwrap() };
79	    (status, value)
80	}
