3	//! Maps `TenancyError` into the HTTP surface's stable error contract: a status code by
4	//! `ErrorClass` and a `{"error": {"code", "message"}}` JSON body. `Internal` never leaks
5	//! its source — it logs and returns a generic message (D-per brief: never leak details).
6	
7	use axum::Json;
8	use axum::http::StatusCode;
9	use axum::response::{IntoResponse, Response};
10	use serde_json::json;
11	
12	use crate::application::error::{ErrorClass, TenancyError};
13	
14	/// Wraps a `TenancyError` so handlers can return it directly via `?` (see the blanket
15	/// `From` impl below) and axum turns it into a JSON error response.
16	pub struct ApiError(pub TenancyError);
17	
18	impl IntoResponse for ApiError {
19	    fn into_response(self) -> Response {
20	        let status = match self.0.class() {
21	            ErrorClass::Validation => StatusCode::BAD_REQUEST,
22	            ErrorClass::NotFound => StatusCode::NOT_FOUND,
23	            ErrorClass::Conflict | ErrorClass::Precondition => StatusCode::CONFLICT,
24	            ErrorClass::Internal => StatusCode::INTERNAL_SERVER_ERROR,
25	        };
26	
27	        let message = if matches!(self.0.class(), ErrorClass::Internal) {
28	            tracing::error!(error = %self.0, code = self.0.code(), "internal error handling HTTP request");
29	            "internal error".to_string()
30	        } else {
31	            self.0.to_string()
32	        };
33	
34	        (status, Json(json!({ "error": { "code": self.0.code(), "message": message } }))).into_response()
35	    }
36	}
37	
38	/// Any error the application layer can hand back (`TenancyError` itself, or anything that
39	/// converts into one) becomes an `ApiError` — lets handlers use `?` against
40	/// `Result<_, TenancyError>` service calls directly.
41	impl<E: Into<TenancyError>> From<E> for ApiError {
42	    fn from(err: E) -> Self {
43	        ApiError(err.into())
44	    }
45	}
