3	//! Postgres-backed `PrincipalRepository` (SeaORM). Maps domain <-> entity models and
4	//! backend errors into the core's `RepositoryError`.
5	
6	use super::entities::{principal, user};
7	use super::map_err;
8	use async_trait::async_trait;
9	use paigasus_iam_core::{Email, Principal, PrincipalId, PrincipalKind, PrincipalRepository, PrincipalStatus, RepositoryError, User};
10	use paigasus_kernel::Prn;
11	use sea_orm::{ActiveModelTrait, DatabaseConnection, EntityTrait, Set, TransactionTrait};
12	
13	// `Clone` lets the composition root (`http::AppState::new`) hold a repo handle inside a
14	// `#[derive(Clone)] CreateUser` — cheap, `DatabaseConnection` clones an `Arc`-backed pool
15	// handle, not a connection.
16	#[derive(Clone)]
17	pub struct PgPrincipalRepository {
18	    db: DatabaseConnection,
19	}
20	
21	impl PgPrincipalRepository {
22	    #[must_use]
23	    pub fn new(db: DatabaseConnection) -> Self {
24	        PgPrincipalRepository { db }
25	    }
26	}
27	
28	#[async_trait]
29	impl PrincipalRepository for PgPrincipalRepository {
30	    async fn create_user(&self, p: &Principal, u: &User) -> Result<(), RepositoryError> {
31	        // Both inserts must commit-or-rollback together: a lone `principal` row left behind
32	        // by a failed `user` insert (e.g. duplicate email) would orphan permanently and turn
33	        // a caller's retry into a spurious `Conflict` on the principal insert.
34	        let txn = self.db.begin().await.map_err(map_err)?;
35	
36	        let principal = principal::ActiveModel {
37	            id: Set(p.id.uuid()),
38	            prn: Set(p.id.canonical()),
39	            kind: Set(p.kind.as_str().to_string()),
40	            status: Set(p.status.as_str().to_string()),
41	            created_at: Set(p.created_at),
42	            updated_at: Set(p.updated_at),
43	        };
44	        principal.insert(&txn).await.map_err(map_err)?;
45	
46	        let user = user::ActiveModel {
47	            principal_id: Set(u.principal_id.uuid()),
48	            email: Set(u.email.as_str().to_string()),
49	            display_name: Set(u.display_name.clone()),
50	            locale: Set(u.locale.clone()),
51	            timezone: Set(u.timezone.clone()),
52	            created_at: Set(u.created_at),
53	            updated_at: Set(u.updated_at),
54	        };
55	        user.insert(&txn).await.map_err(map_err)?;
56	
57	        txn.commit().await.map_err(map_err)?;
58	        Ok(())
59	    }
60	
61	    async fn find_user(&self, id: &PrincipalId) -> Result<Option<(Principal, User)>, RepositoryError> {
62	        let uuid = id.uuid();
63	        let Some(pm) = principal::Entity::find_by_id(uuid).one(&self.db).await.map_err(map_err)? else {
64	            return Ok(None);
65	        };
66	        let Some(um) = user::Entity::find_by_id(uuid).one(&self.db).await.map_err(map_err)? else {
67	            return Ok(None);
68	        };
69	
70	        let prn = Prn::parse(&pm.prn).map_err(|e| RepositoryError::Backend(Box::new(std::io::Error::other(e.to_string()))))?;
71	        let pid = PrincipalId::from_prn(prn);
72	        let kind = PrincipalKind::parse(&pm.kind).ok_or_else(|| RepositoryError::Backend(Box::new(std::io::Error::other("bad kind"))))?;
73	        let status = PrincipalStatus::parse(&pm.status).ok_or_else(|| RepositoryError::Backend(Box::new(std::io::Error::other("bad status"))))?;
74	        let email = Email::parse(&um.email).map_err(|e| RepositoryError::Backend(Box::new(std::io::Error::other(format!("{e}")))))?;
75	
76	        let principal = Principal::new(pid.clone(), kind, status, pm.created_at, pm.updated_at);
77	        let user = User::new(pid, email, um.display_name, um.locale, um.timezone, um.created_at, um.updated_at);
78	        Ok(Some((principal, user)))
79	    }
80	}
